window.I18N.cs = ["Pixel Bloom – Logická hra nonogram","Funkce","Vyzkoušej","Mapy","Jak hrát","Obrázky","Hrát hned","500 obrázků čeká na rozkvět","Vyřeš hádanku.","Odhal obrázek.","Sleduj, jak rozkvétá!","Útulná hra nonogramů. Řiď se číselnými nápovědami, vyplňuj správná políčka a každá úroveň rozkvete v barevný pixelový obrázek.","Vyzkoušej hned","Již brzy","Hra zdarma","Bez účtu","úrovní","kouzelných map","jazyků","Útulné, chytré, barevné","Čistá logika","Každá hádanka má jedno řešení, ke kterému dojdeš přemýšlením. Žádné hádání.","Obrázky, které rozkvétají","Dokonči úroveň a bloky se mezi konfetami promění v barevný obrázek.","Nápovědy, které učí","Nápověda vysvětlí další logický krok na skutečných číslech, takže se naučíš fintu.","Kombo a hvězdy","Řetěz správná políčka a získej až x5 bodů. Hraj bez chyby na 3 hvězdy.","Snadné na naučení","Prvních pět úrovní je přátelský výukový návod krok za krokem.","Stvořeno pro dotyk","Klepnutím vyplníš, tažením vyplníš řadu, dvojklepem dáš X.","Zkus to","Čísla ukazují skupiny vyplněných políček v každém řádku a sloupci. Klepnutím vyplňuj, nebo přepni na ✕ a označ prázdná políčka. Chyba stojí jedno srdce!","Vyplnit","Označit prázdné","Další obrázek","Znovu","Skóre","Obrázek hotový!","Došla srdce. Zkus to znovu!","25 kouzelných map","Od Kopců západu slunce po Divy světa: 500 ručně vytvořených obrázků.","Úrovně {a}–{b}","Jak hrát","Čti nápovědy","Čísla ukazují skupiny vyplněných políček. „2 2“ znamená dva bloky po dvou s mezerou mezi nimi.","Vyplňuj a označuj","Vyplň políčka, kterými si jsi jistý. Prázdná, o kterých víš, označ křížkem X.","Sleduj, jak rozkvétá","Dokonči mřížku a úroveň se promění v barevný pixelový obrázek.","Hra v akci","Obrázek v každé úrovni","Klepni na obrázek a uvidíš jeho název. K objevení je jich 500!","Připraven rozkvést?","Stáhni si Pixel Bloom zdarma a odhal první obrázek za minutu.","Zásady ochrany soukromí","Podpora"];

window.I18N.hu = ["Pixel Bloom – Nonogram logikai játék","Funkciók","Próbáld ki","Térképek","Hogyan játssz","Képek","Játssz most","500 kép vár a kivirágzásra","Old meg a rejtvényt.","Fedd fel a képet.","Nézd, ahogy kivirágzik!","Egy hangulatos nonogram játék. Kövesd a számokat, töltsd ki a helyes mezőket, és minden pálya színes pixelképpé virágzik.","Próbáld ki most","Hamarosan","Ingyenes játék","Fiók nélkül","pálya","varázslatos térkép","nyelv","Hangulatos, okos, színes","Tiszta logika","Minden rejtvénynek egyetlen megoldása van, amelyet gondolkodással érsz el. Nincs találgatás.","Képek, amelyek kivirágoznak","Fejezz be egy pályát, és a blokkok konfettiesőben színes képpé változnak.","Tanító tippek","A tipp valódi számokkal magyarázza el a következő logikus lépést, így megtanulod a trükköt.","Kombók és csillagok","Láncolj helyes mezőket akár x5 pontért. Játssz hibátlanul 3 csillagért.","Könnyen megtanulható","Az első öt pálya egy barátságos, lépésről lépésre haladó bevezető.","Érintésre tervezve","Koppints a kitöltéshez, húzd egy sor kitöltéséhez, koppints duplán az X-hez.","Próbáld ki","A számok az egyes sorokban és oszlopokban lévő kitöltött mezőcsoportokat mutatják. Koppints a kitöltéshez, vagy válts ✕-re az üres mezők jelöléséhez. Egy hibás kitöltés egy szívbe kerül!","Kitöltés","Üres jelölése","Következő kép","Újrakezdés","Pontszám","A kép kész!","Elfogytak a szívek. Próbáld újra!","25 varázslatos térkép","A Naplemente-dombságtól a Világ csodáiig: 500 kézzel készített kép.","{a}–{b}. pálya","Hogyan játssz","Olvasd el a nyomokat","A számok a kitöltött mezők csoportjait mutatják. A „2 2” két kételemű blokkot jelent, köztük egy réssel.","Töltsd ki és jelöld","Töltsd ki azokat a mezőket, amelyekben biztos vagy. Jelöld X-szel, amelyekről tudod, hogy üresek.","Nézd, ahogy kivirágzik","Fejezd be a rácsot, és a pályád színes pixelképpé változik.","A játék működés közben","Minden pályán egy kép","Koppints egy képre a nevéért. 500 kép vár felfedezésre!","Készen állsz a virágzásra?","Töltsd le ingyen a Pixel Bloomot, és fedd fel az első képed egy perc alatt.","Adatvédelmi irányelvek","Támogatás"];

window.I18N.ro = ["Pixel Bloom – Joc de puzzle nonogram","Funcții","Încearcă","Hărți","Cum se joacă","Imagini","Joacă acum","500 de imagini așteaptă să înflorească","Rezolvă puzzle-ul.","Dezvăluie imaginea.","Privește-o cum înflorește!","Un joc de nonograme primitor. Urmează indiciile numerice, completează pătratele corecte, iar fiecare nivel înflorește într-o imagine pixelată colorată.","Încearcă acum","În curând","Gratuit","Fără cont","niveluri","hărți magice","limbi","Primitor, isteț, colorat","Logică pură","Fiecare puzzle are o singură soluție, la care ajungi prin raționament. Fără ghicit.","Imagini care înfloresc","Termină un nivel și blocurile se transformă într-o imagine colorată, cu confetti.","Indicii care te învață","Un indiciu explică următorul pas logic cu numere reale, ca să înveți trucul.","Combo și stele","Înlănțuie pătrate corecte pentru până la x5 puncte. Joacă fără greșeli pentru 3 stele.","Ușor de învățat","Primele cinci niveluri sunt un tutorial prietenos, pas cu pas.","Făcut pentru touch","Atinge pentru a completa, glisează pentru a completa un rând, atinge de două ori pentru un X.","Încearcă","Numerele arată grupurile de pătrate completate din fiecare rând și coloană. Atinge pentru a completa sau treci pe ✕ ca să marchezi pătratele goale. O greșeală costă o inimă!","Completează","Marchează gol","Imaginea următoare","Reîncepe","Scor","Imagine completă!","Nu mai ai inimi. Încearcă din nou!","25 de hărți magice","De la Dealurile Apusului la Minunile Lumii: 500 de imagini făcute cu grijă.","Nivelurile {a}–{b}","Cum se joacă","Citește indiciile","Numerele arată grupuri de pătrate completate. „2 2” înseamnă două blocuri de câte două, cu un spațiu între ele.","Completează și marchează","Completează pătratele de care ești sigur. Marchează cu X pe cele despre care știi că sunt goale.","Privește-o cum înflorește","Completează grila și nivelul tău devine o imagine pixelată colorată.","Jocul în acțiune","O imagine în fiecare nivel","Atinge o imagine ca să-i vezi numele. Sunt 500 de descoperit!","Gata să înflorești?","Descarcă Pixel Bloom gratuit și dezvăluie prima imagine într-un minut.","Politica de confidențialitate","Asistență"];

window.I18N.bg = ["Pixel Bloom – Игра с главоблъсканици нонограми","Функции","Опитай","Карти","Как се играе","Картинки","Играй сега","500 картинки чакат да разцъфнат","Реши пъзела.","Разкрий картинката.","Гледай как разцъфва!","Уютна игра с нонограми. Следвай числовите подсказки, попълвай правилните квадратчета и всяко ниво разцъфтява в цветна пикселна картинка.","Опитай сега","Очаквайте скоро","Безплатна игра","Без акаунт","нива","вълшебни карти","езика","Уютно, умно, цветно","Чиста логика","Всеки пъзел има едно решение, до което стигаш с разсъждение. Без налучкване.","Картинки, които разцъфтяват","Завърши нивото и блоковете се превръщат в цветна картинка с конфети.","Подсказки, които учат","Подсказката обяснява следващата логична стъпка с реални числа, за да научиш трика.","Комбота и звезди","Свързвай верни квадратчета за до x5 точки. Играй безгрешно за 3 звезди.","Лесно за научаване","Първите пет нива са дружелюбно ръководство стъпка по стъпка.","Създадена за докосване","Докосни, за да попълниш, плъзни, за да попълниш ред, докосни два пъти за X.","Опитай","Числата показват групите попълнени квадратчета във всеки ред и колона. Докосвай, за да попълваш, или превключи на ✕, за да отбелязваш празните. Грешка струва едно сърце!","Попълни","Отбележи празно","Следваща картинка","Отначало","Точки","Картинката е готова!","Свършиха сърцата. Опитай пак!","25 вълшебни карти","От Хълмовете на залеза до Чудесата на света: 500 ръчно направени картинки.","Нива {a}–{b}","Как се играе","Чети подсказките","Числата показват групи попълнени квадратчета. „2 2“ означава два блока по две с празно място между тях.","Попълвай и отбелязвай","Попълвай квадратчета, в които си сигурен. Отбелязвай с X тези, за които знаеш, че са празни.","Гледай как разцъфва","Завърши мрежата и нивото ти става цветна пикселна картинка.","Играта в действие","Картинка във всяко ниво","Докосни картинка, за да видиш името ѝ. Има 500 за откриване!","Готов ли си да разцъфнеш?","Изтегли Pixel Bloom безплатно и разкрий първата си картинка за минута.","Политика за поверителност","Поддръжка"];

window.I18N.el = ["Pixel Bloom – Παιχνίδι γρίφων Nonogram","Χαρακτηριστικά","Δοκίμασε","Χάρτες","Πώς παίζεται","Εικόνες","Παίξε τώρα","500 εικόνες περιμένουν να ανθίσουν","Λύσε τον γρίφο.","Αποκάλυψε την εικόνα.","Δες την να ανθίζει!","Ένα ζεστό παιχνίδι nonogram. Ακολούθησε τους αριθμητικούς δείκτες, γέμισε τα σωστά τετράγωνα και κάθε επίπεδο ανθίζει σε μια πολύχρωμη εικόνα pixel.","Δοκίμασε τώρα","Έρχεται σύντομα","Δωρεάν παιχνίδι","Χωρίς λογαριασμό","επίπεδα","μαγικοί χάρτες","γλώσσες","Ζεστό, έξυπνο, πολύχρωμο","Καθαρή λογική","Κάθε γρίφος έχει μία λύση που βρίσκεται με σκέψη. Χωρίς εικασίες.","Εικόνες που ανθίζουν","Ολοκλήρωσε ένα επίπεδο και τα μπλοκ μεταμορφώνονται σε πολύχρωμη εικόνα με κομφετί.","Υποδείξεις που διδάσκουν","Μια υπόδειξη εξηγεί το επόμενο λογικό βήμα με πραγματικούς αριθμούς, για να μάθεις το κόλπο.","Κόμπο και αστέρια","Συνδύασε σωστά τετράγωνα για έως και x5 πόντους. Παίξε άψογα για 3 αστέρια.","Εύκολο στη μάθηση","Τα πρώτα πέντε επίπεδα είναι ένα φιλικό εκπαιδευτικό βήμα προς βήμα.","Φτιαγμένο για αφή","Πάτα για γέμισμα, σύρε για να γεμίσεις μια γραμμή, πάτα δύο φορές για X.","Δοκίμασέ το","Οι αριθμοί δείχνουν τις ομάδες γεμάτων τετραγώνων σε κάθε γραμμή και στήλη. Πάτα για γέμισμα ή άλλαξε σε ✕ για να σημαδέψεις τα κενά. Ένα λάθος κοστίζει μια καρδιά!","Γέμισμα","Σήμανση κενού","Επόμενη εικόνα","Επανεκκίνηση","Βαθμοί","Η εικόνα ολοκληρώθηκε!","Τέλος οι καρδιές. Δοκίμασε ξανά!","25 μαγικοί χάρτες","Από τους Λόφους του Δειλινού έως τα Θαύματα του Κόσμου: 500 χειροποίητες εικόνες.","Επίπεδα {a}–{b}","Πώς παίζεται","Διάβασε τους δείκτες","Οι αριθμοί δείχνουν ομάδες γεμάτων τετραγώνων. Το «2 2» σημαίνει δύο μπλοκ των δύο με ένα κενό ανάμεσα.","Γέμισε και σήμανε","Γέμισε τα τετράγωνα για τα οποία είσαι σίγουρος. Σήμανε με X όσα ξέρεις ότι είναι κενά.","Δες την να ανθίζει","Ολοκλήρωσε το πλέγμα και το επίπεδό σου γίνεται μια πολύχρωμη εικόνα pixel.","Το παιχνίδι σε δράση","Μια εικόνα σε κάθε επίπεδο","Πάτα μια εικόνα για να δεις το όνομά της. Υπάρχουν 500 για να ανακαλύψεις!","Έτοιμος να ανθίσεις;","Κατέβασε δωρεάν το Pixel Bloom και αποκάλυψε την πρώτη σου εικόνα σε ένα λεπτό.","Πολιτική απορρήτου","Υποστήριξη"];

window.I18N.ru = ["Pixel Bloom – Головоломка нонограмма","Особенности","Попробовать","Карты","Как играть","Картинки","Играть","500 картинок ждут, чтобы расцвести","Реши головоломку.","Открой картинку.","Смотри, как она расцветает!","Уютная игра в нонограммы. Следуй числовым подсказкам, закрашивай нужные клетки, и каждый уровень расцветает яркой пиксельной картинкой.","Попробовать сейчас","Скоро","Играть бесплатно","Без аккаунта","уровней","волшебных карт","языков","Уютно, умно, красочно","Чистая логика","У каждой головоломки одно решение, до которого можно дойти рассуждением. Никакого угадывания.","Картинки, которые расцветают","Пройди уровень, и блоки превратятся в яркую картинку под конфетти.","Подсказки, которые учат","Подсказка объясняет следующий логический шаг на реальных числах, чтобы ты освоил приём.","Комбо и звёзды","Соединяй верные клетки и получай до x5 очков. Играй без ошибок на 3 звезды.","Легко научиться","Первые пять уровней — дружелюбное обучение шаг за шагом.","Создано для касаний","Коснись, чтобы закрасить, проведи, чтобы закрасить линию, коснись дважды, чтобы поставить X.","Попробуй сам","Числа показывают группы закрашенных клеток в каждой строке и столбце. Касайся, чтобы закрашивать, или переключись на ✕, чтобы отмечать пустые клетки. Ошибка стоит одного сердца!","Закрасить","Отметить пустой","Следующая картинка","Заново","Очки","Картинка готова!","Сердца закончились. Попробуй ещё раз!","25 волшебных карт","От Холмов заката до Чудес света: 500 картинок ручной работы.","Уровни {a}–{b}","Как играть","Читай подсказки","Числа показывают группы закрашенных клеток. «2 2» значит два блока по две клетки с промежутком между ними.","Закрашивай и отмечай","Закрашивай клетки, в которых уверен. Клетки, которые точно пусты, отмечай крестиком X.","Смотри, как она расцветает","Заполни сетку, и уровень превратится в яркую пиксельную картинку.","Игра в действии","Картинка на каждом уровне","Коснись картинки, чтобы увидеть её название. Всего их 500!","Готов расцвести?","Скачай Pixel Bloom бесплатно и открой первую картинку за минуту.","Политика конфиденциальности","Поддержка"];

window.I18N.uk = ["Pixel Bloom – Головоломка нонограма","Можливості","Спробувати","Мапи","Як грати","Малюнки","Грати","500 малюнків чекають, щоб розквітнути","Розв’яжи головоломку.","Відкрий малюнок.","Дивись, як він розквітає!","Затишна гра в нонограми. Йди за числовими підказками, зафарбовуй потрібні клітинки, і кожен рівень розквітає яскравим піксельним малюнком.","Спробуй зараз","Незабаром","Грати безкоштовно","Без акаунта","рівнів","чарівних мап","мов","Затишно, розумно, барвисто","Чиста логіка","Кожна головоломка має один розв’язок, до якого можна дійти міркуванням. Жодного вгадування.","Малюнки, що розквітають","Пройди рівень, і блоки перетворяться на яскравий малюнок під конфеті.","Підказки, що вчать","Підказка пояснює наступний логічний крок на справжніх числах, щоб ти опанував прийом.","Комбо та зірки","Поєднуй правильні клітинки й отримуй до x5 балів. Грай без помилок на 3 зірки.","Легко навчитися","Перші п’ять рівнів — дружнє навчання крок за кроком.","Створено для дотику","Торкнись, щоб зафарбувати, проведи, щоб зафарбувати лінію, торкнись двічі, щоб поставити X.","Спробуй сам","Числа показують групи зафарбованих клітинок у кожному рядку й стовпці. Торкайся, щоб зафарбовувати, або перемкнись на ✕, щоб позначати порожні клітинки. Помилка коштує одне серце!","Зафарбувати","Позначити порожню","Наступний малюнок","Заново","Бали","Малюнок готовий!","Серця закінчилися. Спробуй ще раз!","25 чарівних мап","Від Пагорбів заходу до Див світу: 500 малюнків ручної роботи.","Рівні {a}–{b}","Як грати","Читай підказки","Числа показують групи зафарбованих клітинок. «2 2» означає два блоки по дві клітинки з проміжком між ними.","Зафарбовуй і позначай","Зафарбовуй клітинки, у яких певен. Клітинки, які точно порожні, познач хрестиком X.","Дивись, як він розквітає","Заповни сітку, і рівень перетвориться на яскравий піксельний малюнок.","Гра в дії","Малюнок на кожному рівні","Торкнись малюнка, щоб побачити його назву. Їх усього 500!","Готовий розквітнути?","Завантаж Pixel Bloom безкоштовно й відкрий перший малюнок за хвилину.","Політика конфіденційності","Підтримка"];

window.I18N.id = ["Pixel Bloom – Game teka-teki nonogram","Fitur","Coba","Peta","Cara bermain","Gambar","Main sekarang","500 gambar menunggu untuk mekar","Pecahkan teka-tekinya.","Ungkap gambarnya.","Lihat gambarnya mekar!","Game nonogram yang nyaman. Ikuti petunjuk angka, isi kotak yang tepat, dan setiap level mekar menjadi gambar piksel yang penuh warna.","Coba sekarang","Segera hadir","Gratis dimainkan","Tanpa akun","level","peta ajaib","bahasa","Nyaman, cerdas, penuh warna","Logika murni","Setiap teka-teki punya satu solusi yang bisa dicapai dengan bernalar. Tanpa menebak.","Gambar yang mekar","Selesaikan level dan blok berubah menjadi gambar penuh warna dengan konfeti.","Petunjuk yang mengajar","Petunjuk menjelaskan langkah logis berikutnya dengan angka nyata, jadi kamu belajar triknya.","Kombo & bintang","Rangkai kotak yang benar untuk hingga x5 poin. Main tanpa salah untuk 3 bintang.","Mudah dipelajari","Lima level pertama adalah tutorial ramah langkah demi langkah.","Dibuat untuk layar sentuh","Ketuk untuk mengisi, geser untuk mengisi satu baris, ketuk dua kali untuk memasang X.","Coba sendiri","Angka menunjukkan kelompok kotak terisi di setiap baris dan kolom. Ketuk untuk mengisi, atau beralih ke ✕ untuk menandai kotak kosong. Salah mengisi mengurangi satu hati!","Isi","Tandai kosong","Gambar berikutnya","Ulangi","Skor","Gambar selesai!","Hati habis. Coba lagi!","25 peta ajaib","Dari Bukit Senja hingga Keajaiban Dunia: 500 gambar buatan tangan.","Level {a}–{b}","Cara bermain","Baca petunjuknya","Angka menunjukkan kelompok kotak terisi. “2 2” berarti dua blok berisi dua dengan jarak di antaranya.","Isi dan tandai","Isi kotak yang kamu yakini. Tandai dengan X kotak yang kamu tahu kosong.","Lihat gambarnya mekar","Selesaikan kisi dan levelmu berubah menjadi gambar piksel penuh warna.","Lihat permainannya beraksi","Satu gambar di setiap level","Ketuk gambar untuk melihat namanya. Ada 500 gambar untuk ditemukan!","Siap untuk mekar?","Unduh Pixel Bloom gratis dan ungkap gambar pertamamu dalam semenit.","Kebijakan Privasi","Dukungan"];

window.I18N.ms = ["Pixel Bloom – Permainan teka-teki nonogram","Ciri-ciri","Cuba","Peta","Cara bermain","Gambar","Main sekarang","500 gambar menunggu untuk berkembang","Selesaikan teka-teki.","Dedahkan gambar.","Lihat ia berkembang!","Permainan nonogram yang selesa. Ikut petunjuk nombor, isi petak yang betul, dan setiap tahap berkembang menjadi gambar piksel yang penuh warna.","Cuba sekarang","Akan datang","Percuma dimainkan","Tanpa akaun","tahap","peta ajaib","bahasa","Selesa, bijak, berwarna-warni","Logik tulen","Setiap teka-teki ada satu penyelesaian yang boleh dicapai dengan berfikir. Tanpa meneka.","Gambar yang berkembang","Selesaikan tahap dan blok bertukar menjadi gambar berwarna dengan konfeti.","Petunjuk yang mengajar","Petunjuk menerangkan langkah logik seterusnya dengan nombor sebenar, supaya anda belajar helahnya.","Kombo & bintang","Rantaikan petak yang betul untuk sehingga x5 mata. Main tanpa silap untuk 3 bintang.","Mudah dipelajari","Lima tahap pertama ialah tutorial mesra langkah demi langkah.","Dibuat untuk skrin sentuh","Ketik untuk mengisi, leret untuk mengisi satu baris, ketik dua kali untuk meletakkan X.","Cubalah","Nombor menunjukkan kumpulan petak berisi dalam setiap baris dan lajur. Ketik untuk mengisi, atau tukar ke ✕ untuk menanda petak kosong. Isian salah mengurangkan satu hati!","Isi","Tanda kosong","Gambar seterusnya","Mula semula","Skor","Gambar siap!","Hati habis. Cuba lagi!","25 peta ajaib","Dari Bukit Senja hingga Keajaiban Dunia: 500 gambar buatan tangan.","Tahap {a}–{b}","Cara bermain","Baca petunjuk","Nombor menunjukkan kumpulan petak berisi. “2 2” bermaksud dua blok berisi dua dengan jarak di antaranya.","Isi dan tanda","Isi petak yang anda pasti. Tanda dengan X petak yang anda tahu kosong.","Lihat ia berkembang","Lengkapkan grid dan tahap anda bertukar menjadi gambar piksel berwarna-warni.","Lihat permainan beraksi","Satu gambar dalam setiap tahap","Ketik gambar untuk melihat namanya. Ada 500 gambar untuk diterokai!","Sedia untuk berkembang?","Muat turun Pixel Bloom percuma dan dedahkan gambar pertama anda dalam seminit.","Dasar Privasi","Sokongan"];

window.I18N.fil = ["Pixel Bloom – Larong nonogram na puzzle","Mga Tampok","Subukan","Mga Mapa","Paano maglaro","Mga Larawan","Maglaro na","500 larawang naghihintay mamukadkad","Lutasin ang puzzle.","Ibunyag ang larawan.","Panoorin itong mamukadkad!","Isang kaaya-ayang nonogram na laro. Sundin ang mga numerong pahiwatig, punan ang tamang mga parisukat, at bawat antas ay mamumukadkad bilang makulay na pixel na larawan.","Subukan ngayon","Malapit na","Libre laruin","Walang account na kailangan","antas","mahiwagang mapa","wika","Kaaya-aya, matalino, makulay","Purong lohika","Bawat puzzle ay may isang solusyon na maaabot sa pangangatwiran. Walang hulaan.","Mga larawang namumukadkad","Tapusin ang antas at magiging makulay na larawan ang mga bloke kasama ng confetti.","Mga pahiwatig na nagtuturo","Ipinaliliwanag ng pahiwatig ang susunod na lohikal na hakbang gamit ang totoong mga numero, kaya matututuhan mo ang trick.","Mga combo at bituin","Pagsunud-sunurin ang tamang mga parisukat para sa hanggang x5 puntos. Maglaro nang walang mali para sa 3 bituin.","Madaling matutuhan","Ang unang limang antas ay isang magiliw na tutorial, hakbang-hakbang.","Gawa para sa touch","Mag-tap para punan, mag-slide para punan ang isang linya, mag-double-tap para maglagay ng X.","Subukan mo","Ipinapakita ng mga numero ang mga grupo ng puno nang parisukat sa bawat hanay at kolum. Mag-tap para punan, o lumipat sa ✕ para markahan ang mga walang laman. Ang maling punan ay kapalit ng isang puso!","Punan","Markahang walang laman","Susunod na larawan","Ulitin","Puntos","Tapos na ang larawan!","Naubos ang mga puso. Subukan muli!","25 mahiwagang mapa","Mula Sunset Hills hanggang World Wonders: 500 larawang gawa sa kamay.","Mga antas {a}–{b}","Paano maglaro","Basahin ang mga pahiwatig","Ipinapakita ng mga numero ang mga grupo ng puno nang parisukat. Ang “2 2” ay dalawang bloke ng tig-dalawa na may puwang sa pagitan.","Punan at markahan","Punan ang mga parisukat na sigurado ka. Markahan ng X ang mga alam mong walang laman.","Panoorin itong mamukadkad","Kumpletuhin ang grid at magiging makulay na pixel na larawan ang antas mo.","Tingnan ang laro sa aksyon","Isang larawan sa bawat antas","Mag-tap ng larawan para makita ang pangalan nito. May 500 na matutuklasan!","Handa nang mamukadkad?","I-download nang libre ang Pixel Bloom at ibunyag ang una mong larawan sa loob ng isang minuto.","Patakaran sa Privacy","Suporta"];

window.I18N.vi = ["Pixel Bloom – Trò chơi giải đố nonogram","Tính năng","Dùng thử","Bản đồ","Cách chơi","Hình ảnh","Chơi ngay","500 bức tranh đang chờ nở hoa","Giải câu đố.","Hé lộ bức tranh.","Xem nó nở hoa!","Trò chơi nonogram ấm cúng. Làm theo gợi ý số, tô đúng các ô, và mỗi màn chơi sẽ nở thành một bức tranh pixel đầy màu sắc.","Thử ngay","Sắp ra mắt","Chơi miễn phí","Không cần tài khoản","màn chơi","bản đồ kỳ diệu","ngôn ngữ","Ấm cúng, thông minh, rực rỡ","Logic thuần túy","Mỗi câu đố có một lời giải duy nhất đạt được bằng suy luận. Không cần đoán mò.","Tranh nở hoa","Hoàn thành màn chơi và các khối biến thành bức tranh đầy màu sắc cùng pháo giấy.","Gợi ý biết dạy","Gợi ý giải thích bước hợp lý tiếp theo bằng số thật, để bạn học được mẹo.","Combo & sao","Nối các ô đúng để nhận tới x5 điểm. Chơi không sai để được 3 sao.","Dễ học","Năm màn đầu là hướng dẫn thân thiện từng bước một.","Sinh ra cho cảm ứng","Chạm để tô, vuốt để tô cả hàng, chạm đúp để đặt dấu X.","Chơi thử","Các số cho biết nhóm ô đã tô ở mỗi hàng và cột. Chạm để tô, hoặc chuyển sang ✕ để đánh dấu ô trống. Tô sai sẽ mất một trái tim!","Tô","Đánh dấu trống","Tranh tiếp theo","Chơi lại","Điểm","Hoàn thành bức tranh!","Hết tim rồi. Thử lại nhé!","25 bản đồ kỳ diệu","Từ Đồi Hoàng Hôn đến Kỳ Quan Thế Giới: 500 bức tranh thủ công.","Màn {a}–{b}","Cách chơi","Đọc gợi ý","Các số cho biết nhóm ô đã tô. “2 2” nghĩa là hai khối hai ô, cách nhau một ô trống.","Tô và đánh dấu","Tô những ô bạn chắc chắn. Đánh dấu X những ô bạn biết là trống.","Xem nó nở hoa","Hoàn thành lưới và màn chơi biến thành bức tranh pixel đầy màu sắc.","Xem trò chơi hoạt động","Mỗi màn một bức tranh","Chạm vào bức tranh để xem tên. Có 500 bức để khám phá!","Sẵn sàng nở hoa chưa?","Tải Pixel Bloom miễn phí và hé lộ bức tranh đầu tiên chỉ trong một phút.","Chính sách quyền riêng tư","Hỗ trợ"];

window.I18N.sw = ["Pixel Bloom – Mchezo wa fumbo la nonogram","Vipengele","Jaribu","Ramani","Jinsi ya kucheza","Picha","Cheza sasa","Picha 500 zinasubiri kuchanua","Tatua fumbo.","Fichua picha.","Itazame ikichanua!","Mchezo wa nonogram wenye starehe. Fuata vidokezo vya namba, jaza miraba sahihi, na kila ngazi huchanua kuwa picha ya pikseli yenye rangi.","Jaribu sasa","Inakuja hivi karibuni","Bure kucheza","Hakuna akaunti inayohitajika","ngazi","ramani za kichawi","lugha","Starehe, werevu, rangi tele","Mantiki safi","Kila fumbo lina suluhisho moja unalolifikia kwa kufikiri. Hakuna kubahatisha.","Picha zinazochanua","Maliza ngazi na vizuizi vitageuka kuwa picha yenye rangi pamoja na confetti.","Vidokezo vinavyofundisha","Kidokezo kinaeleza hatua ifuatayo ya kimantiki kwa namba halisi, ili ujifunze mbinu.","Kombo na nyota","Unganisha miraba sahihi kwa hadi pointi x5. Cheza bila kosa upate nyota 3.","Rahisi kujifunza","Ngazi tano za kwanza ni mafunzo rafiki hatua kwa hatua.","Imeundwa kwa mguso","Gusa kujaza, telezesha kujaza mstari, gusa mara mbili kuweka X.","Jaribu mwenyewe","Namba zinaonyesha makundi ya miraba iliyojazwa kwenye kila safu na safuwima. Gusa kujaza, au badilisha hadi ✕ kuweka alama kwenye miraba tupu. Kujaza vibaya kunagharimu moyo mmoja!","Jaza","Weka alama tupu","Picha inayofuata","Anza upya","Alama","Picha imekamilika!","Mioyo imeisha. Jaribu tena!","Ramani 25 za kichawi","Kutoka Milima ya Machweo hadi Maajabu ya Dunia: picha 500 zilizotengenezwa kwa mkono.","Ngazi {a}–{b}","Jinsi ya kucheza","Soma vidokezo","Namba zinaonyesha makundi ya miraba iliyojazwa. “2 2” inamaanisha vizuizi viwili vya miraba miwili kwa nafasi moja katikati.","Jaza na weka alama","Jaza miraba ambayo una uhakika nayo. Weka X kwenye miraba unayojua ni tupu.","Itazame ikichanua","Kamilisha gridi na ngazi yako itageuka kuwa picha ya pikseli yenye rangi.","Tazama mchezo ukifanya kazi","Picha moja kwa kila ngazi","Gusa picha kuona jina lake. Kuna picha 500 za kugundua!","Tayari kuchanua?","Pakua Pixel Bloom bure na ufichue picha yako ya kwanza ndani ya dakika moja.","Sera ya Faragha","Msaada"];
