window.I18N.ar = ["Pixel Bloom – لعبة ألغاز نونوغرام","المزايا","جرّبها","الخرائط","طريقة اللعب","الصور","العب الآن","500 صورة تنتظر أن تتفتّح","حلّ اللغز.","اكشف الصورة.","شاهدها وهي تتفتّح!","لعبة نونوغرام دافئة. اتبع الأدلة الرقمية، واملأ المربعات الصحيحة، وكل مستوى يتفتّح إلى صورة بكسل ملونة.","جرّبها الآن","قريبًا","مجانية اللعب","بدون حساب","مستوى","خرائط سحرية","لغة","دافئة وذكية وملونة","منطق خالص","لكل لغز حل واحد تصل إليه بالتفكير المنطقي. بلا تخمين.","صور تتفتّح","أنهِ المستوى فتتحول المكعبات إلى صورة ملونة وسط قصاصات الكونفيتي.","تلميحات تعلّمك","يشرح التلميح الخطوة المنطقية التالية بأرقام حقيقية، لتتعلم الحيلة.","كومبو ونجوم","تابع المربعات الصحيحة لتصل إلى x5 من النقاط. العب بلا أخطاء لتنال 3 نجوم.","سهلة التعلّم","المستويات الخمسة الأولى درس تعليمي ودود خطوة بخطوة.","مصممة للمس","المس للتعبئة، واسحب لتعبئة صف كامل، وانقر مرتين لوضع X.","جرّبها بنفسك","تُظهر الأرقام مجموعات المربعات المملوءة في كل صف وعمود. المس للتعبئة، أو بدّل إلى ✕ لتعليم المربعات الفارغة. التعبئة الخاطئة تكلّفك قلبًا!","تعبئة","تعليم فارغ","الصورة التالية","إعادة","النقاط","اكتملت الصورة!","نفدت القلوب. حاول مجددًا!","25 خريطة سحرية","من تلال الغروب إلى عجائب العالم: 500 صورة مصنوعة يدويًا.","المستويات {a}–{b}","طريقة اللعب","اقرأ الأدلة","تُظهر الأرقام مجموعات المربعات المملوءة. «2 2» تعني كتلتين من مربعين بينهما فراغ.","املأ وعلّم","املأ المربعات التي أنت متأكد منها. علّم بـ X المربعات التي تعرف أنها فارغة.","شاهدها وهي تتفتّح","أكمل الشبكة فيتحول مستواك إلى صورة بكسل ملونة.","اللعبة أثناء العمل","صورة في كل مستوى","المس صورة لترى اسمها. هناك 500 صورة لتكتشفها!","هل أنت مستعد للتفتّح؟","نزّل Pixel Bloom مجانًا واكشف صورتك الأولى في دقيقة.","سياسة الخصوصية","الدعم"];

window.I18N.fa = ["Pixel Bloom – بازی معمای نانوگرام","ویژگی‌ها","امتحان کن","نقشه‌ها","نحوه بازی","تصویرها","همین حالا بازی کن","500 تصویر منتظر شکوفا شدن هستند","معما را حل کن.","تصویر را آشکار کن.","شکوفا شدنش را تماشا کن!","یک بازی نانوگرام دنج. سرنخ‌های عددی را دنبال کن، خانه‌های درست را پر کن و هر مرحله به یک تصویر پیکسلی رنگارنگ شکوفا می‌شود.","همین حالا امتحان کن","به‌زودی","بازی رایگان","بدون نیاز به حساب","مرحله","نقشه جادویی","زبان","دنج، هوشمندانه، رنگارنگ","منطق محض","هر معما یک راه‌حل دارد که با استدلال به آن می‌رسی. بدون حدس زدن.","تصویرهایی که شکوفا می‌شوند","مرحله را تمام کن تا بلوک‌ها با کاغذ‌ریزه به یک تصویر رنگارنگ تبدیل شوند.","راهنمایی‌هایی که یاد می‌دهند","راهنما گام منطقی بعدی را با عددهای واقعی توضیح می‌دهد تا ترفند را یاد بگیری.","کمبو و ستاره","خانه‌های درست را پشت‌سرهم پر کن تا تا x5 امتیاز بگیری. بدون اشتباه بازی کن تا 3 ستاره بگیری.","یادگیری آسان","پنج مرحله اول یک آموزش دوستانه و گام‌به‌گام است.","ساخته‌شده برای لمس","برای پر کردن لمس کن، برای پر کردن یک خط بکش، برای گذاشتن X دو بار لمس کن.","امتحانش کن","عددها گروه‌های خانه‌های پرشده را در هر سطر و ستون نشان می‌دهند. برای پر کردن لمس کن یا برای علامت‌زدن خانه‌های خالی به ✕ تغییر بده. هر پر کردن اشتباه یک قلب هزینه دارد!","پر کردن","علامت خالی","تصویر بعدی","شروع دوباره","امتیاز","تصویر کامل شد!","قلب‌ها تمام شد. دوباره تلاش کن!","25 نقشه جادویی","از تپه‌های غروب تا عجایب جهان: 500 تصویر دست‌ساز.","مرحله‌های {a}–{b}","نحوه بازی","سرنخ‌ها را بخوان","عددها گروه‌های خانه‌های پرشده را نشان می‌دهند. «2 2» یعنی دو بلوک دوتایی با یک فاصله بینشان.","پر کن و علامت بزن","خانه‌هایی را که مطمئنی پر کن. خانه‌هایی را که می‌دانی خالی‌اند با X علامت بزن.","شکوفا شدنش را تماشا کن","جدول را کامل کن تا مرحله‌ات به یک تصویر پیکسلی رنگارنگ تبدیل شود.","بازی در عمل","یک تصویر در هر مرحله","برای دیدن نام تصویر آن را لمس کن. 500 تصویر برای کشف وجود دارد!","آماده شکوفا شدن هستی؟","Pixel Bloom را رایگان دانلود کن و اولین تصویرت را در یک دقیقه آشکار کن.","سیاست حریم خصوصی","پشتیبانی"];

window.I18N.ur = ["Pixel Bloom – نونوگرام پہیلی کا کھیل","خصوصیات","آزمائیں","نقشے","کھیلنے کا طریقہ","تصاویر","ابھی کھیلیں","500 تصاویر کھلنے کی منتظر ہیں","پہیلی حل کریں۔","تصویر ظاہر کریں۔","اسے کھلتے دیکھیں!","ایک دلکش نونوگرام کھیل۔ عددی اشاروں پر چلیں، درست خانے بھریں، اور ہر لیول ایک رنگین پکسل تصویر میں کھل اٹھتا ہے۔","ابھی آزمائیں","جلد آ رہا ہے","کھیلنا مفت","اکاؤنٹ کی ضرورت نہیں","لیول","جادوئی نقشے","زبانیں","دلکش، ذہین، رنگین","خالص منطق","ہر پہیلی کا ایک ہی حل ہے جو سوچ سے ملتا ہے۔ اندازے کی ضرورت نہیں۔","کھلتی ہوئی تصاویر","لیول مکمل کریں تو بلاکس کنفیٹی کے ساتھ رنگین تصویر میں بدل جاتے ہیں۔","سکھانے والے اشارے","اشارہ اگلے منطقی قدم کو اصل اعداد کے ساتھ سمجھاتا ہے، تاکہ آپ ترکیب سیکھ لیں۔","کومبو اور ستارے","درست خانے لگاتار بھر کر x5 تک پوائنٹس پائیں۔ بغیر غلطی کھیلیں اور 3 ستارے حاصل کریں۔","سیکھنا آسان","پہلے پانچ لیول ایک دوستانہ قدم بہ قدم ٹیوٹوریل ہیں۔","ٹچ کے لیے بنایا گیا","بھرنے کے لیے ٹیپ کریں، پوری لائن بھرنے کے لیے سلائیڈ کریں، X لگانے کے لیے دو بار ٹیپ کریں۔","خود آزمائیں","اعداد ہر صف اور کالم میں بھرے خانوں کے گروپ دکھاتے ہیں۔ بھرنے کے لیے ٹیپ کریں، یا خالی خانوں کو نشان زد کرنے کے لیے ✕ پر جائیں۔ غلط بھرنے سے ایک دل کم ہوتا ہے!","بھریں","خالی نشان زد کریں","اگلی تصویر","دوبارہ شروع","اسکور","تصویر مکمل!","دل ختم ہو گئے۔ دوبارہ کوشش کریں!","25 جادوئی نقشے","غروب کی پہاڑیوں سے دنیا کے عجائبات تک: 500 ہاتھ سے بنی تصاویر۔","لیول {a}–{b}","کھیلنے کا طریقہ","اشارے پڑھیں","اعداد بھرے خانوں کے گروپ دکھاتے ہیں۔ «2 2» کا مطلب ہے دو، دو کے بلاک جن کے درمیان ایک خالی جگہ ہو۔","بھریں اور نشان لگائیں","وہ خانے بھریں جن کا آپ کو یقین ہے۔ جو خانے خالی ہیں انہیں X سے نشان زد کریں۔","اسے کھلتے دیکھیں","گرڈ مکمل کریں تو آپ کا لیول رنگین پکسل تصویر بن جاتا ہے۔","کھیل کی جھلک","ہر لیول میں ایک تصویر","نام دیکھنے کے لیے تصویر پر ٹیپ کریں۔ دریافت کرنے کو 500 تصاویر ہیں!","کھلنے کے لیے تیار ہیں؟","Pixel Bloom مفت ڈاؤن لوڈ کریں اور ایک منٹ میں اپنی پہلی تصویر ظاہر کریں۔","رازداری کی پالیسی","معاونت"];

